import 'package:firebase_auth/firebase_auth.dart';import 'package:firebase_core/firebase_core.dart';import 'package:flutter/material.dart';import 'core/theme.dart';import 'effects/cosmic_touch.dart';import 'screens/auth.dart';import 'screens/home.dart';import 'screens/keeper.dart';import 'screens/connect.dart';import 'screens/memories.dart';import 'screens/planner.dart';import 'screens/profile.dart';import 'services/services.dart';
Future<void> main()async{WidgetsFlutterBinding.ensureInitialized();await Firebase.initializeApp();await Alerts.i.init();runApp(const Watchkeeper());}
class Watchkeeper extends StatefulWidget{const Watchkeeper({super.key});@override State<Watchkeeper> createState()=>_App();}
class _App extends State<Watchkeeper>{ThemeMode mode=ThemeMode.dark;Color seed=WKTheme.violet;@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'WATCHKEEPER 5',theme:WKTheme.light(seed),darkTheme:WKTheme.dark(seed),themeMode:mode,home:StreamBuilder<User?>(stream:FirebaseAuth.instance.authStateChanges(),builder:(c,s){if(s.connectionState==ConnectionState.waiting)return const Scaffold(body:Center(child:CircularProgressIndicator()));if(s.data==null)return const AuthScreen();DB.ensureProfile();return Shell(onMode:(x)=>setState(()=>mode=x),onSeed:(x)=>setState(()=>seed=x));}));}
class Shell extends StatefulWidget{const Shell({super.key,required this.onMode,required this.onSeed});final ValueChanged<ThemeMode> onMode;final ValueChanged<Color> onSeed;@override State<Shell> createState()=>_Shell();}
class _Shell extends State<Shell>{int i=0;@override Widget build(BuildContext c){final pages=[HomePage(jump:(x)=>setState(()=>i=x)),const KeeperPage(),const ConnectPage(),const MemoriesPage(),const PlannerPage(),ProfilePage(onMode:widget.onMode,onSeed:widget.onSeed)];return CosmicTouch(child:Scaffold(body:IndexedStack(index:i,children:pages),bottomNavigationBar:NavigationBar(selectedIndex:i,onDestinationSelected:(x)=>setState(()=>i=x),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home_rounded),label:'Home'),NavigationDestination(icon:Icon(Icons.auto_awesome_outlined),selectedIcon:Icon(Icons.auto_awesome),label:'Keeper'),NavigationDestination(icon:Icon(Icons.forum_outlined),selectedIcon:Icon(Icons.forum),label:'Connect'),NavigationDestination(icon:Icon(Icons.photo_library_outlined),selectedIcon:Icon(Icons.photo_library),label:'Memories'),NavigationDestination(icon:Icon(Icons.calendar_month_outlined),selectedIcon:Icon(Icons.calendar_month),label:'Planner'),NavigationDestination(icon:Icon(Icons.person_outline),selectedIcon:Icon(Icons.person),label:'Studio')])));}}
